// Hostile and malformed inputs for `buildos intake convert` (W1 R7 P4 review
// fixes). Every source here is generated by the test. Each hostile case runs
// the real CLI in a child process with a small heap (--max-old-space-size)
// and a time limit, and checks that it fails cleanly (exit 1, one
// `buildos-intake: error:` line), stays inside its time budget, and writes
// nothing: not in the project, and not beside it. The malformed-input cases
// pin the Go 1.24.1 intake tool's exact text (captured with the Go seed
// binary on 2026-11-23), so the port keeps Go's `encoding/xml` and
// `ledongthuc/pdf` messages.

import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { chmodSync, linkSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, realpathSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { after, describe, it } from "node:test";
import { fileURLToPath } from "node:url";
import { constants, crc32, deflateRawSync } from "node:zlib";
import { INTAKE_LIMITS } from "../src/core/intake/limits.ts";
import { goQuote } from "../src/core/shared/go-quote.ts";
import { pdf, zip } from "./golden/generate-fixtures.ts";
import { intakeParsers } from "../src/adapters/intake-parsers.ts";
import { compareObservations, loadExceptions, normalizePdfWhitespace, pdfSeparations, pdfWordGapClass, pdfWordGapProblems, type GoldenCase, type Observation } from "./golden/harness.ts";

/** Go's body with each added block and its following blank line removed once (as in intake-eval-parity.test.ts). */
function withoutBlocks(body: string, blocks: readonly string[]): string {
  let out = body;
  for (const block of blocks) {
    const at = out.indexOf(`${block}\n\n`);
    if (at === -1) return `<block not found: ${block}>`;
    out = out.slice(0, at) + out.slice(at + block.length + 2);
  }
  return out;
}

const packageRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const cli = join(packageRoot, "src", "cli", "main.ts");
const base = mkdtempSync(join(tmpdir(), "buildos-intake-hostile-"));
after(() => rmSync(base, { recursive: true, force: true }));

const MiB = 1024 * 1024;
const W = 'xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"';
const para = (t: string) => `<w:p><w:r><w:t>${t}</w:t></w:r></w:p>`;
const docXml = (body: string) => `<?xml version="1.0" encoding="UTF-8"?>\n<w:document ${W}><w:body>${body}</w:body></w:document>`;

interface ZipPart {
  name: string;
  /** Compressed bytes (deflate) and the declared values. */
  raw: Buffer;
  size: number;
  crc: number;
  method?: number;
}

const u16 = (n: number) => Buffer.from([n & 0xff, (n >> 8) & 0xff]);
const u32 = (n: number) => {
  const b = Buffer.alloc(4);
  b.writeUInt32LE(n >>> 0);
  return b;
};

/** A ZIP with deflated entries whose declared size and CRC the test chooses. */
function rawZip(parts: readonly ZipPart[]): Buffer {
  const locals: Buffer[] = [];
  const centrals: Buffer[] = [];
  let offset = 0;
  for (const p of parts) {
    const name = Buffer.from(p.name, "utf8");
    const method = p.method ?? 8;
    const local = Buffer.concat([u32(0x04034b50), u16(20), u16(0x0800), u16(method), u16(0), u16(0x21), u32(p.crc), u32(p.raw.length), u32(p.size), u16(name.length), u16(0), name, p.raw]);
    centrals.push(
      Buffer.concat([u32(0x02014b50), u16(20), u16(20), u16(0x0800), u16(method), u16(0), u16(0x21), u32(p.crc), u32(p.raw.length), u32(p.size), u16(name.length), u16(0), u16(0), u16(0), u16(0), u32(0), u32(offset), name]),
    );
    locals.push(local);
    offset += local.length;
  }
  const central = Buffer.concat(centrals);
  return Buffer.concat([...locals, central, u32(0x06054b50), u16(0), u16(0), u16(parts.length), u16(parts.length), u32(central.length), u32(offset), u16(0)]);
}

/**
 * A ZIP whose central directory lists every part, but whose local data is
 * stored only for the first two: every later entry points at the second
 * part's local header (overlapping entries).
 */
function overlappingZip(parts: readonly ZipPart[]): Buffer {
  const locals: Buffer[] = [];
  const centrals: Buffer[] = [];
  let offset = 0;
  let shared = 0;
  const centralOf = (p: ZipPart, name: Buffer, at: number) =>
    Buffer.concat([u32(0x02014b50), u16(20), u16(20), u16(0x0800), u16(8), u16(0), u16(0x21), u32(p.crc), u32(p.raw.length), u32(p.size), u16(name.length), u16(0), u16(0), u16(0), u16(0), u32(0), u32(at), name]);
  parts.forEach((p, i) => {
    const name = Buffer.from(p.name, "utf8");
    if (i >= 2) {
      centrals.push(centralOf(p, name, shared));
      return;
    }
    const local = Buffer.concat([u32(0x04034b50), u16(20), u16(0x0800), u16(8), u16(0), u16(0x21), u32(p.crc), u32(p.raw.length), u32(p.size), u16(name.length), u16(0), name, p.raw]);
    if (i === 1) shared = offset;
    locals.push(local);
    centrals.push(centralOf(p, name, offset));
    offset += local.length;
  });
  const central = Buffer.concat(centrals);
  return Buffer.concat([...locals, central, u32(0x06054b50), u16(0), u16(0), u16(parts.length), u16(parts.length), u32(central.length), u32(offset), u16(0)]);
}

const deflated = (data: Buffer): ZipPart["raw"] => deflateRawSync(data);
const honest = (name: string, data: Buffer): ZipPart => ({ name, raw: deflated(data), size: data.length, crc: crc32(data) });

/** A deflate stream of `mib` MiB of zeros, built from one compressed MiB repeated (about 1 KiB per MiB). */
function zeroBomb(mib: number): Buffer {
  const chunk = deflateRawSync(Buffer.alloc(MiB), { finishFlush: constants.Z_SYNC_FLUSH });
  return Buffer.concat([...Array.from({ length: mib }, () => chunk), Buffer.from([0x03, 0x00])]);
}

interface Outcome {
  status: number | null;
  stdout: string;
  stderr: string;
  ms: number;
  /** Files under the project after the run, other than the source. */
  written: string[];
  /** Files beside the project after the run (the canary folder). */
  beside: string[];
  /** The child's peak resident set size, in MiB (`process.resourceUsage().maxRSS`). */
  maxRssMiB: number;
}

/** Peak resident memory a hostile case may reach, with the JavaScript heap capped at 256 MiB. */
const RSS_CAP_MIB = 1024;

let caseNumber = 0;

/** Runs `buildos intake convert --source <name>` on one generated source, with a small heap and a time limit. */
function convertHostile(name: string, data: Buffer, extra: string[] = [], setup?: (project: string, outside: string) => void): Outcome {
  const dir = join(base, `case-${++caseNumber}`);
  const project = join(dir, "project");
  const outside = join(dir, "outside");
  mkdirSync(project, { recursive: true });
  mkdirSync(outside, { recursive: true });
  writeFileSync(join(outside, "canary.txt"), "canary");
  writeFileSync(join(project, name), data);
  setup?.(project, outside);
  const rssFile = join(dir, "max-rss.txt");
  const recordRss = `data:text/javascript,import{writeFileSync}from"node:fs";process.on("exit",()=>writeFileSync(${JSON.stringify(rssFile)},String(process.resourceUsage().maxRSS)))`;
  const start = performance.now();
  const r = spawnSync(process.execPath, ["--max-old-space-size=256", "--import", recordRss, cli, "intake", "convert", "--source", name, ...extra], { cwd: project, encoding: "utf8", timeout: 90_000 });
  const ms = performance.now() - start;
  let maxRssMiB = Number.NaN;
  try {
    maxRssMiB = Number(readFileSync(rssFile, "utf8")) / 1024;
  } catch {
    // The child died before its exit handler ran; the status check reports it.
  }
  const list = (root: string) => (readdirSync(root, { recursive: true, withFileTypes: true }) as { isFile(): boolean; name: string; parentPath: string }[]).filter((e) => e.isFile()).map((e) => join(e.parentPath, e.name).slice(root.length + 1));
  return { status: r.status, stdout: r.stdout, stderr: r.stderr, ms, written: list(project).filter((p) => p !== name), beside: list(outside), maxRssMiB };
}

/** A hostile source fails cleanly with exactly `message`, quickly, and writes nothing anywhere. */
function assertRefused(outcome: Outcome, message: string, budgetMs = 20_000): void {
  assert.equal(outcome.stderr, `buildos-intake: error: ${message}\n`);
  assert.equal(outcome.status, 1);
  assert.equal(outcome.stdout, "");
  assert.deepEqual(outcome.written, []);
  assert.deepEqual(outcome.beside, ["canary.txt"]);
  assert.ok(outcome.ms < budgetMs, `took ${Math.round(outcome.ms)} ms`);
  assert.ok(outcome.maxRssMiB < RSS_CAP_MIB, `peak memory ${Math.round(outcome.maxRssMiB)} MiB`);
}

describe("intake hostile inputs: ZIP", () => {
  it("refuses a ZIP bomb whose entry declares its real expanded size, before inflating it", () => {
    const raw = zeroBomb(300);
    const out = convertHostile("bomb.docx", rawZip([{ name: "word/document.xml", raw, size: 300 * MiB, crc: 0 }]));
    assertRefused(out, `zip: the entry "word/document.xml" (${300 * MiB} bytes expanded) exceeds the BuildOS input limit (256 MiB per entry)`);
  });

  it("stops a ZIP bomb that declares a small size as soon as the real output passes it", () => {
    const out = convertHostile("liar.docx", rawZip([{ name: "word/document.xml", raw: zeroBomb(200), size: 4096, crc: 0 }]));
    assertRefused(out, "zip: not a valid zip file", 10_000);
  });

  it("refuses an entry whose compression ratio is past the limit", () => {
    const out = convertHostile("ratio.xlsx", rawZip([{ name: "xl/workbook.xml", raw: zeroBomb(100), size: 100 * MiB, crc: 0 }]));
    assertRefused(out, `zip: the compression ratio of the entry "xl/workbook.xml" exceeds the BuildOS input limit (${INTAKE_LIMITS.zipMaxRatio} to 1)`);
  });

  it("refuses an archive with more entries than the limit, from the central directory", () => {
    const parts = Array.from({ length: INTAKE_LIMITS.zipMaxEntries + 1 }, (_, i) => honest(`word/media/i${i}.bin`, Buffer.from("x")));
    const out = convertHostile("many.docx", rawZip(parts));
    assertRefused(out, `zip: the entry count ${INTAKE_LIMITS.zipMaxEntries + 1} exceeds the BuildOS input limit (${INTAKE_LIMITS.zipMaxEntries} entries)`);
  });

  for (const name of ["word/media/../../../../evil.png", "../evil.png", "/tmp/evil.png", "C:/evil.png", "word\\media\\..\\..\\evil.png", "word/media/a\0b.png"]) {
    it(`refuses the unsafe entry name ${JSON.stringify(name)} before anything is written`, () => {
      const out = convertHostile("traversal.docx", rawZip([honest("word/document.xml", Buffer.from(docXml(para("x")))), honest(name, Buffer.from("png"))]));
      assertRefused(out, `zip: insecure file path ${goQuote(name)}`);
    });
  }

  it("refuses a corrupt CRC as Go does", () => {
    const data = Buffer.from(docXml(para("x")));
    const out = convertHostile("crc.docx", rawZip([{ ...honest("word/document.xml", data), crc: 1 }]));
    assertRefused(out, "zip: checksum error");
  });

  it("writes no media when the document that comes with it is invalid (PE-013)", () => {
    const out = convertHostile("media.docx", zip([["word/media/image1.png", "png"], ["word/document.xml", docXml("<w:p>")]]));
    assertRefused(out, "XML syntax error on line 2: element <p> closed by </body>");
  });
});

describe("intake hostile inputs at production scale, under a memory cap", () => {
  // Each source is at or past a real limit, not a scaled-down copy. Every
  // case runs with a 256 MiB JavaScript heap, must stay under RSS_CAP_MIB of
  // peak resident memory, and must fail cleanly and write nothing.
  const wb = (extra = "") => `<workbook xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">${extra}<sheets><sheet name="S" r:id="rId1"/></sheets></workbook>`;
  const rels = `<Relationships><Relationship Id="rId1" Target="worksheets/sheet1.xml"/></Relationships>`;
  const attrs = (n: number) => Array.from({ length: n }, (_, i) => `a${i}=""`).join(" ");
  const sheet = (sharedXml: string, rows: number) =>
    zip([
      ["xl/workbook.xml", wb()],
      ["xl/_rels/workbook.xml.rels", rels],
      ["xl/sharedStrings.xml", sharedXml],
      ["xl/worksheets/sheet1.xml", `<worksheet><sheetData>${Array.from({ length: rows }, (_, r) => `<row><c r="A${r + 1}" t="s"><v>0</v></c></row>`).join("")}</sheetData></worksheet>`],
    ]);

  it("one element with 2,000,000 attributes in a streamed part stops at the attribute count, as each is read", () => {
    const out = convertHostile("attrs.docx", zip([["word/document.xml", `<w:document ${W}><w:body><w:p ${attrs(2_000_000)}/></w:body></w:document>`]]));
    assertRefused(out, `xml: the attribute count of an element on line 1 exceeds the BuildOS input limit (${INTAKE_LIMITS.xmlMaxAttributes} attributes)`);
  });

  it("one attribute value of 20 MiB stops at the attribute size, as it is read", () => {
    const out = convertHostile("attr-size.docx", zip([["word/document.xml", `<w:document ${W}><w:body><w:p a="${"x".repeat(20 * MiB)}"/></w:body></w:document>`]]));
    assertRefused(out, `xml: the attribute size of an element on line 1 exceeds the BuildOS input limit (${INTAKE_LIMITS.xmlMaxAttributeBytes / MiB} MiB per element)`);
  });

  it("1,080,000 attributes in a parsed part (the workbook) are charged to the tree budget as they are read", () => {
    const xlsx = zip([["xl/workbook.xml", wb(Array.from({ length: 120 }, () => `<x ${attrs(9_000)}/>`).join(""))], ["xl/_rels/workbook.xml.rels", rels], ["xl/worksheets/sheet1.xml", "<worksheet/>"]]);
    assertRefused(convertHostile("attrs-tree.xlsx", xlsx), `xml: the node count of a parsed part exceeds the BuildOS input limit (${INTAKE_LIMITS.xmlMaxNodes} nodes)`);
  });

  it("a flood of 1,000,001 sibling elements in a parsed part stops at the tree budget", () => {
    const xlsx = zip([["xl/workbook.xml", wb("<x/>".repeat(1_000_001))], ["xl/_rels/workbook.xml.rels", rels], ["xl/worksheets/sheet1.xml", "<worksheet/>"]]);
    assertRefused(convertHostile("siblings.xlsx", xlsx), `xml: the node count of a parsed part exceeds the BuildOS input limit (${INTAKE_LIMITS.xmlMaxNodes} nodes)`);
  });

  it("9,000 ZIP entries that overlap one 1 MiB entry stop at the total expanded size", () => {
    const media = honest("word/media/m0.png", Buffer.alloc(MiB));
    const parts = [honest("word/document.xml", Buffer.from(docXml(para("x")))), ...Array.from({ length: 9_000 }, (_, i) => ({ ...media, name: `word/media/m${i}.png` }))];
    const out = convertHostile("overlap.docx", overlappingZip(parts));
    assertRefused(out, `zip: the expanded size of the entries read exceeds the BuildOS input limit (${INTAKE_LIMITS.zipMaxTotalBytes / MiB} MiB in all)`);
  });

  it("2,000,001 shared strings stop at the shared string count", () => {
    const out = convertHostile("shared-count.xlsx", sheet(`<sst>${"<si><t>x</t></si>".repeat(INTAKE_LIMITS.xlsxMaxSharedStrings + 1)}</sst>`, 1));
    assertRefused(out, `xlsx: the shared string count exceeds the BuildOS input limit (${INTAKE_LIMITS.xlsxMaxSharedStrings} strings)`);
  });

  it("65 MiB of shared string text stops at the shared string text budget", () => {
    const out = convertHostile("shared-text.xlsx", sheet(`<sst>${`<si><t>${"y".repeat(MiB)}</t></si>`.repeat(65)}</sst>`, 1));
    assertRefused(out, `xlsx: the shared string text exceeds the BuildOS input limit (${INTAKE_LIMITS.xlsxMaxSharedStringChars} characters)`);
  });

  it("one 1 MiB shared string in 200 cells (a shared-string bomb) stops at the CSV size", () => {
    const out = convertHostile("shared-bomb.xlsx", sheet(`<sst><si><t>${"y".repeat(MiB)}</t></si></sst>`, 200));
    assertRefused(out, `xlsx: the CSV size of a worksheet exceeds the BuildOS input limit (${INTAKE_LIMITS.xlsxMaxCsvBytes / MiB} MiB)`);
  });

  it("one PDF page with 70 million characters of text stops reading at the text budget", () => {
    const line = `(${"w".repeat(50_000)}) Tj 0 -0.5 Td`;
    const data = pdf([{ ops: [`BT /F1 0.01 Tf 72 720 Td ${Array.from({ length: 1_400 }, () => line).join("\n")} ET`] }]);
    assertRefused(convertHostile("huge-page.pdf", data), `pdf: the extracted text exceeds the BuildOS input limit (${INTAKE_LIMITS.pdfMaxTextChars} characters)`, 60_000);
  });
});

describe("intake preflight: every destination is checked before the first write", () => {
  // The HTML page has one image, so Go's order writes the side artifact
  // `media/page-image-001.png` before the twin `page.md`. A twin the port
  // refuses must stop the command before the side artifact is written.
  const page = Buffer.from('<html><body><p>Hi</p><img src="data:image/png;base64,iVBORw0KGgo="></body></html>');
  const twinFolder = (project: string) => {
    const folder = join(project, "system", "assets", "page");
    mkdirSync(folder, { recursive: true });
    return folder;
  };
  const posixOnly = { skip: process.platform === "win32" ? "FIFOs and hard links on POSIX" : false };

  it("a twin that is a FIFO: exit 3, and no side artifact", posixOnly, () => {
    const out = convertHostile("page.html", page, ["--force"], (project) => {
      assert.equal(spawnSync("mkfifo", [join(twinFolder(project), "page.md")]).status, 0);
    });
    assert.equal(out.stderr, "buildos-intake: error: system/assets/page/page.md is not a regular file\n");
    assert.equal(out.status, 3);
    assert.deepEqual(out.written, []);
    assert.deepEqual(out.beside, ["canary.txt"]);
  });

  // PE-013 (approved 2026-11-23): where a condition at the twin exists
  // before the convert, Go writes the side artifact and then fails. The
  // port fails with Go's exit code and text and writes nothing. PE-013
  // pins exactly these cases and the port's result for each.
  const notRoot = { skip: process.platform === "win32" ? "POSIX permissions" : typeof process.getuid === "function" && process.getuid() === 0 ? "root ignores permissions" : false };
  const preflight: [string, string[], (folder: string) => void, string[], typeof posixOnly][] = [
    ["preflight-twin-directory-force", ["--force"], (folder) => mkdirSync(join(folder, "page.md")), [], { skip: false }],
    ["preflight-twin-exists", [], (folder) => writeFileSync(join(folder, "page.md"), "old"), [join("system", "assets", "page", "page.md")], { skip: false }],
    [
      "preflight-twin-read-only-force",
      ["--force"],
      (folder) => {
        writeFileSync(join(folder, "page.md"), "old");
        chmodSync(join(folder, "page.md"), 0o444);
      },
      [join("system", "assets", "page", "page.md")],
      notRoot,
    ],
    [
      "preflight-twin-folder-read-only-force",
      ["--force"],
      (folder) => {
        mkdirSync(join(folder, "media"));
        chmodSync(folder, 0o555);
      },
      [],
      notRoot,
    ],
  ];
  const pe013 = loadExceptions().exceptions.find((p) => p.id === "PE-013")?.hostile ?? [];
  it("PE-013 lists exactly the preflight cases where Go leaves a side artifact", () => {
    assert.deepEqual(pe013.map((h) => h.case), preflight.map(([name]) => name));
  });
  for (const [name, extra, setup, kept, skip] of preflight) {
    it(`${name}: Go's exit code and text, and no side artifact (PE-013)`, skip, () => {
      let folder = "";
      let project = "";
      const out = convertHostile("page.html", page, extra, (dir) => {
        project = dir;
        folder = twinFolder(dir);
        setup(folder);
      });
      chmodSync(folder, 0o755);
      const entry = pe013.find((h) => h.case === name);
      assert.ok(entry !== undefined, `PE-013 does not list ${name}`);
      const stderr = [realpathSync(project), project].reduce((text, spelling) => text.split(spelling).join("{PROJECT}"), out.stderr);
      // PE-013 pins Go's POSIX text. Go on Windows prints the same path with
      // its separator (`filepath.Join`; the win32 golden
      // `intake-convert-existing-output` shows `{ROOT}\system\assets\...`), so
      // only the separators of the `{PROJECT}` path change there.
      const allowed = process.platform === "win32" ? { ...entry.allowed, stderr: entry.allowed.stderr.replace(/\{PROJECT\}\S*/g, (p) => p.replaceAll("/", "\\")) } : entry.allowed;
      assert.deepEqual({ exit: out.status, stdout: out.stdout, stderr }, allowed);
      assert.deepEqual(out.written, kept);
      assert.deepEqual(out.beside, ["canary.txt"]);
    });
  }

  it("a twin with a second hard link outside the project: exit 3, no side artifact, and the outside file keeps its bytes", posixOnly, () => {
    let linked = "";
    const out = convertHostile("page.html", page, ["--force"], (project, outside) => {
      linked = join(outside, "linked.md");
      writeFileSync(linked, "outside body");
      linkSync(linked, join(twinFolder(project), "page.md"));
    });
    assert.equal(out.stderr, "buildos-intake: error: system/assets/page/page.md has 2 hard links; the port writes in place only to a file with one link\n");
    assert.equal(out.status, 3);
    assert.deepEqual(out.written, [join("system", "assets", "page", "page.md")]);
    assert.equal(readFileSync(linked, "utf8"), "outside body");
  });
});

describe("intake hostile inputs: XML, HTML, XLSX, and PDF", () => {
  it("never expands DTD entities (billion laughs)", () => {
    let dtd = '<!ENTITY lol "lol">';
    for (let i = 1; i <= 9; i++) dtd += `<!ENTITY lol${i} "${`&lol${i === 1 ? "" : i - 1};`.repeat(10)}">`;
    const xml = `<?xml version="1.0"?><!DOCTYPE lolz [${dtd}]><w:document ${W}><w:body>${para("&lol9;")}</w:body></w:document>`;
    assertRefused(convertHostile("laughs.docx", zip([["word/document.xml", xml]])), "XML syntax error on line 1: invalid character entity &lol9;");
  });

  it("never loads an external entity", () => {
    const xml = `<?xml version="1.0"?><!DOCTYPE d [<!ENTITY xxe SYSTEM "file:///etc/passwd">]><w:document ${W}><w:body>${para("&xxe;")}</w:body></w:document>`;
    assertRefused(convertHostile("xxe.docx", zip([["word/document.xml", xml]])), "XML syntax error on line 1: invalid character entity &xxe;");
  });

  it("refuses XML nested past the limit", () => {
    const depth = INTAKE_LIMITS.xmlMaxDepth + 5;
    const xml = `<w:document ${W}>${"<w:x>".repeat(depth)}${"</w:x>".repeat(depth)}</w:document>`;
    assertRefused(convertHostile("deep.docx", zip([["word/document.xml", xml]])), `xml: element nesting on line 1 exceeds the BuildOS input limit (${INTAKE_LIMITS.xmlMaxDepth} levels)`);
  });

  it("refuses HTML nested 100,000 levels deep, in bounded time", () => {
    const html = `<html><body>${"<div>".repeat(100_000)}deep${"</div>".repeat(100_000)}</body></html>`;
    assertRefused(convertHostile("deep.html", Buffer.from(html)), `html: the element nesting exceeds the BuildOS input limit (${INTAKE_LIMITS.htmlMaxDepth} levels)`);
  });

  it("refuses a sparse XLSX cell reference past the last column, before allocating the row", () => {
    for (const ref of ["XFE1", "ZZZZZZZZZZZZ1"]) {
      const xlsx = zip([
        ["xl/workbook.xml", `<workbook xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="S" r:id="rId1"/></sheets></workbook>`],
        ["xl/_rels/workbook.xml.rels", `<Relationships><Relationship Id="rId1" Target="worksheets/sheet1.xml"/></Relationships>`],
        ["xl/worksheets/sheet1.xml", `<worksheet><sheetData><row><c r="${ref}"><v>1</v></c></row></sheetData></worksheet>`],
      ]);
      const width = INTAKE_LIMITS.xlsxMaxColumns + 1;
      assertRefused(convertHostile("sparse.xlsx", xlsx), `xlsx: the column count ${width} of row 1 exceeds the BuildOS input limit (${INTAKE_LIMITS.xlsxMaxColumns} columns)`);
    }
  });

  it("refuses a sheet whose rows together allocate more cells than the limit", () => {
    const rows = Math.ceil(INTAKE_LIMITS.xlsxMaxCells / INTAKE_LIMITS.xlsxMaxColumns) + 1;
    const xlsx = zip([
      ["xl/workbook.xml", `<workbook><sheets><sheet name="S"/></sheets></workbook>`],
      ["xl/_rels/workbook.xml.rels", `<Relationships/>`],
      ["xl/worksheets/sheet1.xml", `<worksheet><sheetData>${'<row><c r="XFD1"><v>1</v></c></row>'.repeat(rows)}</sheetData></worksheet>`],
    ]);
    assertRefused(convertHostile("cells.xlsx", xlsx), `xlsx: the worksheet cell count exceeds the BuildOS input limit (${INTAKE_LIMITS.xlsxMaxCells} cells)`);
  });

  it("refuses a PDF with more pages than the limit", () => {
    const pages = Array.from({ length: INTAKE_LIMITS.pdfMaxPages + 1 }, () => ({ texts: [{ x: 72, y: 720, text: "p" }] }));
    assertRefused(convertHostile("pages.pdf", pdf(pages)), `pdf: the page count ${INTAKE_LIMITS.pdfMaxPages + 1} exceeds the BuildOS input limit (${INTAKE_LIMITS.pdfMaxPages} pages)`, 30_000);
  });
});

describe("intake malformed inputs match the Go intake tool", () => {
  // stderr of Go 1.24.1 buildos-intake for each source.
  const docx = (xml: string | Buffer) => zip([["word/document.xml", xml]]);
  const cases: [string, Buffer, string][] = [
    ["nbsp.docx", docx(docXml(para("a&nbsp;b"))), "XML syntax error on line 2: invalid character entity &nbsp;"],
    ["mismatch.docx", docx(docXml("<w:p><w:r><w:t>x</w:r></w:p>")), "XML syntax error on line 2: element <t> closed by </r>"],
    ["unclosed.docx", docx(docXml("<w:p><w:r><w:t>x").replace("</w:body></w:document>", "")), "XML syntax error on line 2: unexpected EOF"],
    ["latin1.docx", docx('<?xml version="1.0" encoding="ISO-8859-1"?><w:document/>'), 'xml: encoding "ISO-8859-1" declared but Decoder.CharsetReader is nil'],
    ["badname.docx", docx(docXml("<w:p><1a/></w:p>")), "XML syntax error on line 2: invalid XML name: 1a"],
    ["ctrl.docx", docx(docXml(para("a&#0;b"))), "XML syntax error on line 2: illegal character code U+0000"],
    ["badutf.docx", docx(Buffer.concat([Buffer.from(docXml(para("a")).slice(0, 120)), Buffer.from([0xff]), Buffer.from(docXml(para("a")).slice(120))])), "XML syntax error on line 2: invalid UTF-8"],
    ["nosemi.docx", docx(docXml(para("a &amp b"))), "XML syntax error on line 2: invalid character entity &amp (no semicolon)"],
    ["badattr.docx", docx(docXml("<w:p w:x=1>x</w:p>")), "XML syntax error on line 2: unquoted or missing attribute value in element"],
    ["badwb.xlsx", zip([["xl/workbook.xml", "<workbook><sheets><sheet name='a'></sheets></workbook>"], ["xl/_rels/workbook.xml.rels", "<Relationships/>"]]), "XML syntax error on line 1: element <sheet> closed by </sheets>"],
    ["notzip.docx", Buffer.from("PK not a zip"), "zip: not a valid zip file"],
    ["empty.pdf", Buffer.alloc(0), "open pdf: not a PDF file: invalid header"],
    ["garbage.pdf", Buffer.from("hello world"), "open pdf: not a PDF file: invalid header"],
    ["short.pdf", Buffer.from("%PDF-1.4\n%%EOF\n"), "open pdf: not a PDF file: missing %%EOF"],
    ["nostartxref.pdf", Buffer.from(`%PDF-1.4\n${"x".repeat(200)}\n%%EOF\n`), "open pdf: malformed PDF file: missing final startxref"],
  ];
  for (const [name, data, message] of cases) {
    it(`${name}: exit 1 with Go's text`, () => assertRefused(convertHostile(name, data), message));
  }

  // Malformed PDF trailers. Go's pdf.NewReader reads the startxref operand
  // and the cross-reference section it points at before any page; the port
  // runs a port of those checks (go-pdf-xref.ts). Each text is Go 1.24.1's.
  const good = pdf([{ texts: [{ x: 72, y: 700, text: "Hello trailer" }] }]).toString("latin1");
  const at = good.lastIndexOf("startxref\n");
  const head = good.slice(0, at);
  const xrefAt = good.lastIndexOf("xref\n0 ");
  const trailerAt = good.lastIndexOf("trailer\n");
  const tail = (operand: string) => Buffer.from(`${head}startxref\n${operand}\n%%EOF\n`, "latin1");
  const before = (text: string) => Buffer.from(`${head}${text}\nstartxref\n${at}\n%%EOF\n`, "latin1");
  const edited = (from: string | RegExp, to: string) => Buffer.from(good.replace(from, to), "latin1");
  const xrefStream = (hdr: string) => before(`9 0 obj\n<< ${hdr} >>\nstream\nxx\nendstream\nendobj`);
  const trailers: [string, Buffer, string][] = [
    ["nonnumeric", tail("abc"), "malformed PDF file: startxref not followed by integer"],
    ["real", tail("12.5"), "malformed PDF file: startxref not followed by integer"],
    ["name", tail("/Name"), "malformed PDF file: startxref not followed by integer"],
    ["string", tail("(12)"), "malformed PDF file: startxref not followed by integer"],
    ["zero", tail("0"), "malformed PDF: cross-reference table not found: {1 0 obj}<</Pages 2 0 R /Type /Catalog>>"],
    ["to-trailer", tail(String(trailerAt)), "malformed PDF: cross-reference table not found: trailer"],
    ["no-size", edited(/\/Size \d+ /, ""), "malformed PDF: trailer missing /Size entry"],
    ["bad-xref-row", edited("0000000000 65535 f \n", "0000000000 65535 x \n"), "malformed PDF: malformed xref table"],
    ["prev-name", edited("/Size ", "/Prev /X /Size "), "malformed PDF: xref Prev is not integer: X"],
    ["prev-array", edited("/Size ", "/Prev [1 (a) /B] /Size "), "malformed PDF: xref Prev is not integer: [1 a B]"],
    ["prev-zero", edited("/Size ", "/Prev 0 /Size "), "malformed PDF: xref Prev does not point to xref"],
    ["trailer-array", edited(/trailer\n<<[^]*?>>\n/, "trailer\n[1 2]\n"), "malformed PDF: xref table not followed by trailer dictionary"],
    ["xs-no-type", xrefStream("/Size 3 /W [1 2 1]"), "malformed PDF: xref stream does not have type XRef"],
    ["xs-no-size", xrefStream("/Type /XRef /W [1 2 1]"), "malformed PDF: xref stream missing Size"],
    ["xs-bad-w", xrefStream("/Type /XRef /Size 3 /W [1 2]"), "malformed PDF: invalid W array [1 2]"],
    ["xs-no-w", xrefStream("/Type /XRef /Size 3"), "malformed PDF: xref stream missing W array"],
    ["xs-odd-index", xrefStream("/Type /XRef /Size 3 /Index [0] /W [1 2 1]"), "malformed PDF: invalid Index array [0]"],
    ["xs-not-stream", before("9 0 obj\n<< /Type /XRef /Size 3 /S (hi) >>\nendobj"), 'malformed PDF: cross-reference table not found: {9 0 obj}<</S "hi" /Size 3 /Type /XRef>>'],
    ["xs-int-only", before("9 x"), "malformed PDF: cross-reference table not found: 9"],
    ["true-kw", before("true"), "malformed PDF: cross-reference table not found: true"],
    ["real-kw", before("1234567.5"), "malformed PDF: cross-reference table not found: 1.2345675e+06"],
  ];
  for (const [name, data, message] of trailers) {
    it(`trailer ${name}.pdf: exit 1 with Go's text`, () => assertRefused(convertHostile(`${name}.pdf`, data), `open pdf: ${message}`));
  }
  it("trailer +offset.pdf: a signed startxref is still an integer, as Go reads it", () => {
    const out = convertHostile("plus.pdf", tail(`+${xrefAt}`));
    assert.equal(out.status, 0, out.stderr);
  });

  // Where Go's lexer panics (Go exits 2 with a stack trace), the port exits 1
  // with the panic's message. Where Go loops forever, the port stops at a limit.
  const panics: [string, Buffer, string][] = [
    ["past-eof", tail("99999999"), "open pdf: malformed PDF: reading at offset 99999999: EOF"],
    ["huge-int", tail("99999999999999999999"), "open pdf: invalid integer 99999999999999999999"],
    ["nothing", Buffer.from(`${head}startxref\n%%EOF\n`, "latin1"), `open pdf: malformed PDF: reading at offset ${head.length + 16}: EOF`],
    ["negative", tail("-5"), "open pdf: malformed PDF: reading at offset -5: negative offset"],
    ["prev-self", edited("/Size ", `/Prev ${xrefAt} /Size `), `pdf: the /Prev cross-reference chain exceeds the BuildOS input limit (${INTAKE_LIMITS.pdfMaxXrefSections} sections)`],
    ["deep", before(`9 0 obj\n${"[".repeat(INTAKE_LIMITS.pdfMaxObjectDepth + 1)}`), `pdf: the object nesting exceeds the BuildOS input limit (${INTAKE_LIMITS.pdfMaxObjectDepth} levels)`],
  ];
  // Approved PE-015 (owner decision 2026-11-23) pins exactly these cases
  // and the port's result for each.
  const pe015 = loadExceptions().exceptions.find((p) => p.id === "PE-015")?.hostile ?? [];
  it("PE-015 lists exactly the cases where Go crashes or hangs", () => {
    assert.deepEqual(pe015.map((h) => h.case), panics.map(([name]) => name));
  });
  for (const [name, data, message] of panics) {
    it(`trailer ${name}.pdf: exit 1 where Go crashes or hangs (PE-015)`, () => {
      const out = convertHostile(`${name}.pdf`, data);
      assertRefused(out, message);
      const entry = pe015.find((h) => h.case === name);
      assert.ok(entry !== undefined, `PE-015 does not list ${name}`);
      assert.deepEqual({ exit: out.status, stdout: out.stdout, stderr: out.stderr }, entry.allowed);
    });
  }

  // Go 1.24.1 twin bodies (after the front matter) for well-formed edge cases.
  const bodies: [string, string, string][] = [
    ["doctype.docx", `<?xml version="1.0"?><!DOCTYPE d [<!ENTITY e "x"> <!-- c --> ]><w:document ${W}><w:body>${para("ok &amp; &#65;&#x42; &#xD800;")}</w:body></w:document>`, "ok & AB \uFFFD\n"],
    ["tworoots.docx", `<w:document ${W}><w:body>${para("one")}</w:body></w:document><w:document ${W}><w:body>${para("two")}</w:body></w:document>`, "one\n\ntwo\n"],
    ["cdata.docx", `<w:document ${W}><w:body><w:p><w:r><w:t><![CDATA[<raw> & ]]></w:t><w:t>a\r\nb\rc</w:t></w:r></w:p></w:body></w:document>`, "<raw> & a b c\n"],
    ["ns.docx", `<x:document xmlns:x="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns="urn:d"><x:body><p><t>default-ns p is still local p</t></p>${para("unbound").replace(/w:/g, "q:")}</x:body></x:document>`, "default-ns p is still local p\n\nunbound\n"],
    // U+FEFF is text wherever it appears (Go keeps it): at the start of a
    // CDATA section, in text, as a character reference, and before the
    // XML declaration.
    ["bom.docx", `\ufeff<?xml version="1.0"?>\n<w:document ${W}><w:body><w:p><w:r><w:t><![CDATA[\ufeffx]]></w:t><w:t>a<![CDATA[\ufeff]]>b</w:t><w:t>\ufeffy&#xFEFF;z</w:t></w:r></w:p></w:body></w:document>`, "\ufeffxa\ufeffb\ufeffy\ufeffz\n"],
  ];
  it("bom.xlsx: a U+FEFF at the start of a CDATA section in a shared string and in a cell keeps Go's body", () => {
    const sheet = (lead: string) =>
      zip([
        ["xl/workbook.xml", `${lead}<workbook xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="S" r:id="rId1"/></sheets></workbook>`],
        ["xl/_rels/workbook.xml.rels", `<Relationships><Relationship Id="rId1" Target="worksheets/sheet1.xml"/></Relationships>`],
        ["xl/sharedStrings.xml", `${lead}<sst><si><t><![CDATA[\ufeffc]]></t></si><si><t>\ufeffd</t></si></sst>`],
        ["xl/worksheets/sheet1.xml", `${lead}<worksheet><sheetData><row><c r="A1" t="s"><v>0</v></c><c r="B1" t="s"><v>1</v></c></row></sheetData></worksheet>`],
      ]);
    for (const lead of ["", "\ufeff"]) {
      const out = convertHostile("bom.xlsx", sheet(lead));
      assert.equal(out.status, 0, out.stderr);
      const twin = readFileSync(join(base, `case-${caseNumber}`, "project", "system", "assets", "bom", "bom-s.csv"), "utf8");
      // Go 1.24.1's body.
      assert.equal(twin.split("---\n")[2], "\ufeffc,\ufeffd\n");
    }
  });

  for (const [name, xml, body] of bodies) {
    it(`${name}: the twin body equals Go's`, () => {
      const out = convertHostile(name, docx(xml));
      assert.equal(out.status, 0, out.stderr);
      const stem = name.replace(/\.docx$/, "");
      const twin = readFileSync(join(base, `case-${caseNumber}`, "project", "system", "assets", stem, `${stem}.md`), "utf8");
      assert.equal(twin.split("---\n")[2], body);
    });
  }
});

describe("HTML: parts Go writes inside an inline element of a div keep Go's handling", () => {
  it("writes the image and SVG side artifacts of a span inside a div, as Go does, plus only the added text", () => {
    const html = '<html><body><div>Lead text <span>see <img src="data:image/png;base64,iVBORw0KGgo=" alt="Plan"> and <svg width="2"><rect width="1" height="1"/></svg> done</span> tail</div></body></html>';
    const out = convertHostile("callout.html", Buffer.from(html));
    assert.equal(out.status, 0, out.stderr);
    // `written` lists paths with the OS separator, and Go prints the side
    // artifact paths with it too (`filepath.Join`; the win32 goldens show
    // `{ROOT}\system\assets\...\media\...`). Same files on every OS.
    assert.deepEqual(out.written.sort(), [join("system", "assets", "callout", "callout.md"), join("system", "assets", "callout", "diagrams", "callout-svg-001.svg"), join("system", "assets", "callout", "media", "callout-image-001.png")]);
    const sepPattern = process.platform === "win32" ? "\\\\" : "\\/";
    assert.match(out.stdout, new RegExp(`wrote side artifact .*media${sepPattern}callout-image-001\\.png\\nwrote side artifact .*diagrams${sepPattern}callout-svg-001\\.svg\\n$`));
    const project = join(base, `case-${caseNumber}`, "project", "system", "assets", "callout");
    const body = readFileSync(join(project, "callout.md"), "utf8").split("---\n")[2]!;
    // Go 1.24.1's body for this file, and the SVG it writes.
    const go = "![Plan](media/callout-image-001.png)\n\n![SVG diagram](diagrams/callout-svg-001.svg)\n";
    assert.equal(body, "Lead text see\n\n![Plan](media/callout-image-001.png)\n\nand\n\n![SVG diagram](diagrams/callout-svg-001.svg)\n\ndone tail\n");
    assert.equal(withoutBlocks(body.replace(/\n\ndone tail\n$/, "\n"), ["Lead text see", "and"]), go);
    assert.equal(readFileSync(join(project, "diagrams", "callout-svg-001.svg"), "utf8"), '<svg width="2"><rect width="1" height="1"></rect></svg>');
  });
});

describe("PDF word gaps (PE-009, approved class): checked as a class, with fixtures", () => {
  const fixtures = loadExceptions().exceptions.find((p) => p.id === "PE-009")?.pdf ?? [];
  const fixture = (source: string) => {
    const entry = fixtures.find((e) => e.source === source);
    assert.ok(entry !== undefined, `PE-009 has no fixture ${source}`);
    return entry;
  };
  /** Converts one generated PDF with the real CLI and returns its body and the PDF's separations. */
  const convertPdf = async (name: string, data: Buffer): Promise<{ body: string; separations: string }> => {
    const out = convertHostile(name, data);
    assert.equal(out.status, 0, out.stderr);
    const stem = name.replace(/\.pdf$/, "");
    const body = readFileSync(join(base, `case-${caseNumber}`, "project", "system", "assets", stem, `${stem}.txt`), "utf8").split("---\n")[2]!;
    return { body, separations: pdfSeparations(await intakeParsers.pdfText(new Uint8Array(data))) };
  };
  // Each Go text is Go 1.24.1's body for the same PDF.
  const cases: [string, string, string, string][] = [
    ["fixture:pdf-minutes-two-lines", "minutes.pdf", "BT /F1 16 Tf 72 720 Td (Minutes) Tj 0 -20 Td /F1 11 Tf (May meeting) Tj ET", "\nMinutesMay meeting"],
    ["fixture:pdf-quarterly-staff-meeting", "quarterly.pdf", "BT /F1 12 Tf 72 700 Td (Quarterly) Tj 60 0 Td (Staff meeting) Tj ET", "\nQuarterlyStaff meeting"],
    ["fixture:pdf-quarterly-staff-meeting-tj", "quarterly.pdf", "BT /F1 12 Tf 72 700 Td [(Quarterly) -400 (Staff) 0 ( meeting)] TJ ET", "\nQuarterlyStaff meeting"],
  ];
  for (const [source, name, op, go] of cases) {
    it(`${source}: passes the class check, with exactly the recorded spaces`, async () => {
      const { body, separations } = await convertPdf(name, pdf([{ ops: [op] }]));
      assert.deepEqual(pdfWordGapProblems("PE-009", fixture(source), go, body, separations), []);
    });
  }

  it("fails on a space the PDF does not render, a dropped Go space, and any other change", async () => {
    const { separations } = await convertPdf("quarterly.pdf", pdf([{ ops: ["BT /F1 12 Tf 72 700 Td (Quarterly) Tj 60 0 Td (Staff meeting) Tj ET"] }]));
    const go = "\nQuarterlyStaff meeting";
    assert.deepEqual(pdfWordGapClass(go, "Quarterly Staff meeting", separations), { problems: [], removed: [9] });
    // A space inside a word that the PDF draws as one run.
    assert.equal(pdfWordGapClass(go, "Quar terlyStaff meeting", separations).problems.length, 1);
    assert.equal(pdfWordGapClass(go, "Quarterly Staff mee ting", separations).problems.length, 1);
    // A dropped space that Go has, a changed letter, and an added letter.
    assert.equal(pdfWordGapClass(go, "Quarterly Staffmeeting", separations).problems.length, 1);
    assert.equal(pdfWordGapClass(go, "Quarterly Staff meetinG", separations).problems.length, 1);
    assert.equal(pdfWordGapClass(go, "Quarterly Staff meetings", separations).problems.length, 1);
    // The port's text with no added space is not what the PDF renders here.
    assert.equal(pdfWordGapClass(go, "QuarterlyStaff meeting", separations).problems.length, 1);
    // Two spaces where Go has none collapse to one under normalization, and a
    // space where Go already has one is not an added space.
    assert.deepEqual(pdfWordGapClass("a b", "a \n b", "a b"), { problems: [], removed: [] });
    assert.equal(normalizePdfWhitespace(" a\n\tb "), "a b");
    // A recorded fixture fails when the class check finds other spaces.
    assert.equal(pdfWordGapProblems("PE-009", { ...fixture("fixture:pdf-quarterly-staff-meeting"), inserted_spaces: [8] }, go, "Quarterly Staff meeting", separations).length, 1);
  });

  it("the golden harness applies the class check to PDF twins, with the source PDF's separations", () => {
    const probe: GoldenCase = { id: "pdf-probe", tool: "buildos-intake", domain: "intake", invocation: "buildos-intake", args: [], fixture: null, kind: "success", exit: 0, pdf_text: true };
    const twin = (body: string) => Buffer.from(`---\nsource: "q.pdf"\n---\n${body}`);
    const observe = (body: string): Observation => ({ exit: 0, stdout: Buffer.alloc(0), stderr: Buffer.alloc(0), added: [{ path: "q.txt", kind: "file" }], changed: [], removed: [], files: new Map([["q.txt", twin(body)]]) });
    const go = observe("\nQuarterlyStaff meeting");
    const separations = "Quarterly\u0001Staff meeting";
    assert.deepEqual(compareObservations(probe, go, observe("Quarterly Staff meeting"), { pdfSeparations: separations }), []);
    assert.deepEqual(compareObservations(probe, go, observe("Quarterly Staff meeting")).map((d) => d.field), ["file:q.txt"]);
    assert.deepEqual(compareObservations(probe, go, observe("Quarterly Staff meetinG"), { pdfSeparations: separations }).map((d) => d.field), ["file:q.txt"]);
  });

  // Review round 3: the class check runs in both directions on every PDF
  // twin, also when the port's text equals Go's. The reviewer's three
  // probes: a port that keeps Go's joined words fails, for a `Td` gap, a
  // `TJ` gap, and a line move.
  for (const [source, name, op, go] of cases) {
    it(`golden harness probe ${source}: a port body equal to Go's joined words fails; the rendered gaps pass`, async () => {
      const { body, separations } = await convertPdf(name, pdf([{ ops: [op] }]));
      const probe: GoldenCase = { id: "pdf-probe", tool: "buildos-intake", domain: "intake", invocation: "buildos-intake", args: [], fixture: null, kind: "success", exit: 0, pdf_text: true };
      const twin = (text: string) => Buffer.from(`---\nsource: "q.pdf"\n---\n${text}`);
      const observe = (text: string): Observation => ({ exit: 0, stdout: Buffer.alloc(0), stderr: Buffer.alloc(0), added: [{ path: "q.txt", kind: "file" }], changed: [], removed: [], files: new Map([["q.txt", twin(text)]]) });
      const options = { pdfSeparations: separations, pdfClass: true };
      const joined = compareObservations(probe, observe(go), observe(go), options);
      assert.deepEqual(joined.map((d) => d.field), ["file:q.txt"], "a port body equal to Go's must fail where the PDF renders a word gap");
      assert.match(joined[0]!.detail, /not the PDF's runs with one space at each word separation/);
      assert.deepEqual(compareObservations(probe, observe(go), observe(body), options), []);
    });
  }

  it("golden harness: a PDF twin with no source separations fails when the class check is on, and a PDF with no word gap passes when equal", () => {
    const probe: GoldenCase = { id: "pdf-probe", tool: "buildos-intake", domain: "intake", invocation: "buildos-intake", args: [], fixture: null, kind: "success", exit: 0, pdf_text: true };
    const observe = (text: string): Observation => ({ exit: 0, stdout: Buffer.alloc(0), stderr: Buffer.alloc(0), added: [{ path: "q.txt", kind: "file" }], changed: [], removed: [], files: new Map([["q.txt", Buffer.from(`---\nsource: "q.pdf"\n---\n${text}`)]]) });
    assert.match(compareObservations(probe, observe("\nab cd"), observe("\nab cd"), { pdfClass: true })[0]?.detail ?? "", /separations are missing/);
    assert.deepEqual(compareObservations(probe, observe("\nab cd"), observe("ab\n cd"), { pdfSeparations: "ab cd", pdfClass: true }), []);
    assert.deepEqual(compareObservations(probe, observe("\nab cd"), observe("\nab cd")), []);
  });

  it("pdfSeparations marks run boundaries on a new line, a new page, and a wide gap, and nothing else", () => {
    const run = (str: string, x: number, y: number, width = str.length * 6, size = 12) => ({ str, x, y, width, size });
    assert.equal(pdfSeparations([[run("ab", 0, 700), run("cd", 12, 700)]]), "abcd");
    assert.equal(pdfSeparations([[run("ab", 0, 700), run("cd", 20, 700)]]), "ab\u0001cd");
    assert.equal(pdfSeparations([[run("ab", 0, 700), run("cd", 12, 680)]]), "ab\u0001cd");
    assert.equal(pdfSeparations([[run("ab", 0, 700)], [run("cd", 12, 700)]]), "ab\u0001cd");
    assert.equal(pdfSeparations([[run("ab ", 0, 700), run("cd", 40, 700)]]), "ab cd");
    assert.equal(pdfSeparations([[run(" ab", 0, 700), run("", 40, 700), run("c\td ", 60, 700)]]), "ab\u0001c d");
  });
});
